    vector<ll> parent;

    DisjointSetUnion(ll n) {
        parent.resize(n);
        for (ll i = 0; i < n; ++i) {
            parent[i] = i;
        }
    }

    ll find(ll a) {
        if (parent[a] == a) return a;
        parent[a] = find(parent[a]);
        return parent[a];
    }

