import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    static class DisjointSetUnion {
        long[] parent;

        public DisjointSetUnion(int n) {
            parent = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public long find(long a) {
            if (parent[(int)a] == a) return a;
            parent[(int)a] = find(parent[(int)a]);
            return parent[(int)a];
        }

        public void unite(long a, long b) {
            a = find(a);
            b = find(b);
            if (a != b) {
                Random rand = new Random();
                if (rand.nextInt(2) == 0) {
                    long temp = a;
                    a = b;
                    b = temp;
                }
                parent[(int)b] = a;
            }
        }
    }

    static long computeCycles(int total, int multiplier) {
        DisjointSetUnion dsu = new DisjointSetUnion(total);
        for (int i = 1; i < total; i++) {
            int target = (multiplier * i) % total;
            dsu.unite(i, target);
        }
        boolean[] visited = new boolean[total];
        long cycleCount = 0;
        for (int i = 1; i < total; i++) {
            long root = dsu.find(i);
            if (!visited[(int)root]) {
                visited[(int)root] = true;
                cycleCount++;
            }
        }
        return cycleCount;
    }

    static long calculateSolutions(int total, int multiplier) {
        long cycles;
        if (multiplier == 0) {
            cycles = total - 1;
        } else if (multiplier == 1) {
            cycles = total;
        } else {
            cycles = computeCycles(total, multiplier);
        }
        long result = 1;
        for (int i = 0; i < cycles; i++) {
            result = (result * total) % MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total = sc.nextInt();
        int multiplier = sc.nextInt();
        long answer = calculateSolutions(total, multiplier);
        System.out.println(answer);
        int dummy = sc.nextInt(); // read dummy input
        sc.close();
    }
}
